macroScript AI_Mesh_CleanupTool
category:"3DFlowHub"
toolTip:"AI 메시 파츠 정리"
(
    fn cleanAIMeshes = (
        undo "AI Mesh Cleanup" on
        (
            local sel = selection as array
            if sel.count == 0 then (
                messageBox "정리할 오브젝트를 선택해주세요." title:"AI Cleanup"
                return false
            )

            for obj in sel do (
                -- Reset XForm for AI imported meshes
                ResetXForm obj
                convertTo obj Editable_Poly

                -- Center pivot to bottom
                local bb = obj.max - obj.min
                obj.pivot = [obj.center.x, obj.center.y, obj.min.z]

                -- Clean name
                obj.name = uniqueName "AI_Part_"
            )

            messageBox "선택된 AI 메시 정리가 완료되었습니다." title:"AI Cleanup"
        )
    )

    on execute do (
        cleanAIMeshes()
    )
)
